mapper.select:
SELECT * FROM booking
WHERE user_id = #{userId}
ORDER BY date DESC, start_time DESC

SELECT * FROM booking
WHERE user_id = #{userId}
AND date BETWEEN #{startDate} AND #{endDate}
ORDER BY date DESC, start_time DESC

SELECT * FROM booking
WHERE room_id = #{roomId}
AND date = #{date}
AND status NOT IN ('CANCELLED')
ORDER BY start_time

SELECT COUNT(*)
FROM booking
WHERE room_id = #{roomId}
AND date = #{date}
AND status NOT IN ('CANCELLED')

    AND id != #{excludeBookingId}

AND (
    (start_time < #{endTime} AND end_time > #{startTime})
)

SELECT * FROM booking
WHERE status IN ('PENDING', 'SIGNED_IN')
AND CONCAT(date, ' ', end_time) <= #{beforeTime}
